import { Component, OnInit, Input, Output, EventEmitter } from '@angular/core';
import { CreateSecurity, Issuer, SecuritiesService, Security, TypeSecurity } from './securities.service';
import { LoginService } from '../auth/login/login.service';
import { FormGroup } from '@angular/forms';

@Component({
  selector: 'app-securities',
  templateUrl: './securities.component.html',
  styleUrls: ['./securities.component.css']
})
export class SecuritiesComponent implements OnInit {
  @Input() securityToEdit?: Security;
  @Output() close = new EventEmitter<Security | null>();

  addEditForm!: FormGroup;
  types: TypeSecurity[] = [];
  issuers: Issuer[] = [];

  //securities: Security[] = [];
  //loading:boolean = true;
  //errorMessage: string | null = null;
  //showDeleteModal = false;
  //securityToDelete: Security | null = null;
  //currentUserId: number | null = null;

  constructor(private fb: FormBuilder,private securitiesService: SecuritiesService, public loginService: LoginService) { }

  ngOnInit(): void {
    this.loadSecurities();
  }

  loadSecurities(): void {
    this.securitiesService.getAll().subscribe({
      next: (securities) => {
        this.securities = securities;
        this.loading = false;
      },
      error: (error) => {
        this.errorMessage = 'Could not load securities.';
        this.loading = false;
      }
    });
  }

  openDeleteModal(security: Security): void {
    this.securityToDelete = security;
    this.showDeleteModal = true;
  }

  closeDeleteModal(): void {
    this.showDeleteModal = false;
    this.securityToDelete = null;
  }

  confirmDelete(): void {
    if (!this.securityToDelete) return;

    this.securitiesService.deleteSecurity(this.securityToDelete.id).subscribe({
      next: () => {
        this.loadSecurities();
        this.closeDeleteModal();
      },
      error: (err) => {
        console.error('Failed to delete security:', err);
        this.errorMessage = 'Failed to delete security.';
        this.closeDeleteModal();
      }
    });
  }
}
